        wr::<usize>(ci1 + 0x08, sp);
        wr::<usize>(ci1 + 0x10, base + 0x60);
        wr::<usize>(ci1 + 0x18, code.as_ptr() as usize);
        wr::<i32>(ci1 + 0x20, 1);
